  const protest=events.filter(e=>["politics","protest","movement"].includes(e.kind));
  if(serious.length){ unsafe += Math.min(45, serious.length*14); reasons.push(`${serious.length} serious event signals near the radius`); }
  if(protest.length){ unsafe += Math.min(20, protest.length*5); reasons.push(`${protest.length} unrest/movement disruption signals nearby`); }
  if(crime.available && Number.isFinite(Number(crime.total))){ const total=Number(crime.total); unsafe += Math.min(22, Math.max(0,total-15)*0.4); reasons.push(`${total} local police records in sampled radius`); sourceBreakdown.push("crime: official local"); } else { unsafe += 6; sourceBreakdown.push("crime: no official local source"); }
  const med=(infra.counts&&((infra.counts.hospital||0)+(infra.counts.clinic||0)+(infra.counts.pharmacy||0)))||0; if(med===0){ unsafe += 5; reasons.push("no medical facility returned by infrastructure source inside radius"); } else { unsafe -= Math.min(8, med); reasons.push(`${med} medical/pharmacy facilities mapped in radius`); }
  const police=(infra.counts&&(infra.counts.police||0))||0; if(police===0){ unsafe += 2; } else { unsafe -= 4; reasons.push(`${police} police/security facilities mapped nearby`); }
  if(advisory && advisory.level && /avoid|against all travel|do not travel/i.test(advisory.level)){ unsafe += 30; reasons.push("official travel advisory indicates avoid/do not travel"); }
